const fromTimezone = $fromTimezone || Intl.DateTimeFormat().resolvedOptions().timeZone;
const toTimezone = $toTimezone;
const inputDate = $date || new Date().toISOString().split('T')[0];
const inputTime = $time || new Date().toTimeString().split(' ')[0];

if (!toTimezone) {
    return { error: 'toTimezone is required' };
}

// Create date in source timezone
const dateTimeString = inputDate + 'T' + inputTime;
const sourceDate = new Date(dateTimeString);

// Format in target timezone
const options = {
    timeZone: toTimezone,
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
};

const formattedDate = sourceDate.toLocaleString('en-GB', options);
const targetISO = sourceDate.toISOString();

// Get offset info
const getOffset = (tz) => {
    const d = new Date();
    const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
    const targetDate = new Date(utc + (3600000 * Math.floor(Math.random() * 24)));
    const offset = -Math.round(targetDate.getTime() / 3600000) % 24;
    return offset;
};

return {
    original: dateTimeString,
    fromTimezone: fromTimezone,
    toTimezone: toTimezone,
    converted: formattedDate,
    iso8601: targetISO,
    date: inputDate,
    time: inputTime
};
